// Build one dedupe key per article. Guid first, link as fallback.
// Articles without any identifier are dropped instead of polluting the table.
return items
  .map((item) => {
    const f = item.json;
    const key = String(f.guid || f.link || '').trim();
    return {
      key,
      title: String(f.title || '').trim(),
      link: String(f.link || '').trim(),
      content: String(f.contentSnippet || f.content || '').slice(0, 4000),
      isoDate: f.isoDate || new Date().toISOString(),
    };
  })
  .filter((a) => a.key !== '')
  .map((a) => ({ json: { eventId: a.key, title: a.title, link: a.link, content: a.content, isoDate: a.isoDate } }));

// Two jobs, both required:
//  1. Stop the run when the key is already taken. A Postgres node that gets 0 rows emits
//     { success: true } instead of an empty output, so filtering is what actually stops it.
//  2. Put the original payload back. The claim node outputs the SQL row, so without this
//     every downstream node would read fields that no longer exist.
return items
  .filter((item) => item.json && item.json.key)
  .map((item) => ({
    json: Object.assign({}, item.json.payload || {}, { claimKey: item.json.key }),
  }));
